import pyautogui
import cv2
import numpy as np
import time
from datetime import datetime
import threading

class ScreenRecorder:  
    def __init__(self, output_path=None, fps=20.0):
        """  
        Cross-platform screen recording utility  

        Args:  
            output_path: Custom output directory  
            fps: Frames per second  
        """
        # Screen dimensions
        screen_size = pyautogui.size()
        self.width, self.height = screen_size[0], screen_size[1]

        # Default output path
        if not output_path:
            output_path = f"recording_{datetime.now().strftime('%Y%m%d_%H%M%S')}.avi"

        # Video writer configuration  
        fourcc = cv2.VideoWriter_fourcc(*'XVID')
        self.out = cv2.VideoWriter(output_path, fourcc, fps, (self.width, self.height))

        self.is_recording = False

    def start_recording(self):
        """Start screen recording""" 
        self.is_recording = True
        self._record_thread = threading.Thread(target=self._record_screen)
        self._record_thread.start()

    def stop_recording(self):
        """Stop screen recording"""  
        self.is_recording = False
        self._record_thread.join()
        self.out.release()
        cv2.destroyAllWindows()

    def _record_screen(self):
        """Internal screen recording method"""  
        while self.is_recording:
            # Capture screen  
            img = pyautogui.screenshot()
            frame = np.array(img)

            # Convert RGB to BGR (OpenCV requirement)
            frame = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)

            # Write frame  
            self.out.write(frame)

            # Optional: Control frame rate
            time.sleep(1/20)  # 20 FPS